#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Constants for maximum field lengths
#define MAX_TITLE 100
#define MAX_CONTENT 1000
#define MAX_TIME 30
#define FILE_NAME "journal.csv"

/**
 * Structure to represent a single journal entry
 * Contains entry identifier, title, content, and creation timestamp
 */
typedef struct {
    int id;
    char title[MAX_TITLE];
    char content[MAX_CONTENT];
    char time[MAX_TIME];
} journal_entry;

// Function prototypes
void show_menu();
void show_entries();
void add_entry();
void remove_entry();
void remove_all();
int make_id();
void get_time(char* buffer);

/**
 * Main program function - handles user input and menu navigation
 */
int main() {
    int choice;

    // Initialize random seed for ID generation
    srand(time(NULL));

    do {
        // Display menu and get user selection
        show_menu();
        printf("Enter your choice: ");
        scanf("%d", &choice);
        getchar(); // Consume newline character after scanf

        // Process user selection
        switch (choice) {
            case 1:
                show_entries();
                break;
            case 2:
                add_entry();
                break;
            case 3:
                remove_entry();
                break;
            case 4:
                remove_all();
                break;
            case 5:
                printf("Exiting program. Goodbye!\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }

        // Pause before returning to menu
        printf("\nPress Enter to continue...");
        getchar();

    } while (choice != 5);

    return 0;
}

/**
 * Displays the main application menu with all available options
 * Clears the screen before displaying for better user experience
 */
void show_menu() {
    // Clear screen (works on both Windows and Unix-like systems)
    system("clear || cls");

    printf("\n===== PERSONAL JOURNAL APPLICATION =====\n");
    printf("1. Display all journal entries\n");
    printf("2. Create a new entry\n");
    printf("3. Delete an entry\n");
    printf("4. Delete all entries\n");
    printf("5. Exit the program\n");
    printf("========================================\n");
}

/**
 * Creates a formatted timestamp string with current date and time
 * Format: YYYY-MM-DD H:MM AM/PM
 * 
 * @param buffer Pointer to a character buffer to store the timestamp
 */
void get_time(char* buffer) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);

    // Format the date portion (YYYY-MM-DD)
    char date[20];
    strftime(date, sizeof(date), "%Y-%m-%d", t);

    // Format the time portion with AM/PM
    char time_str[20];
    char am_pm[3] = "AM";
    int hour = t->tm_hour;

    // Convert to 12-hour format with AM/PM
    if (hour >= 12) {
        strcpy(am_pm, "PM");
        if (hour > 12) {
            hour -= 12;
        }
    }
    if (hour == 0) {
        hour = 12;
    }

    sprintf(time_str, "%d:%02d %s", hour, t->tm_min, am_pm);

    // Combine date and time parts
    sprintf(buffer, "%s %s", date, time_str);
}

/**
 * Displays all journal entries from the storage file in tabular format
 * Shows ID, title, timestamp, and content for each entry
 */
void show_entries() {
    FILE *file = fopen(FILE_NAME, "r");

    // Check if file exists or is empty
    if (file == NULL) {
        printf("No journal entries found.\n");
        return;
    }

    journal_entry entry;
    char line[MAX_TITLE + MAX_CONTENT + MAX_TIME + 20];

    // Print table header
    printf("\n%-10s %-30s %-20s %-50s\n", "ID", "TITLE", "TIMESTAMP", "CONTENT");
    printf("-------------------------------------------------------------------------------------\n");

    int count = 0;

    // Read and display each entry
    while (fgets(line, sizeof(line), file)) {
        sscanf(line, "%d,%[^,],%[^,],%[^\n]", 
               &entry.id, 
               entry.title, 
               entry.content, 
               entry.time);

        printf("%-10d %-30s %-20s %-50s\n", 
               entry.id, 
               entry.title, 
               entry.time, 
               entry.content);
        count++;
    }

    if (count == 0) {
        printf("No journal entries found.\n");
    }

    fclose(file);
}

/**
 * Generates a random 4-digit ID for new journal entries
 * 
 * @return A random integer between 1000-9999
 */
int make_id() {
    return rand() % 9000 + 1000;
}

/**
 * Creates a new journal entry by collecting input from the user
 * Saves the entry to the storage file with a unique ID and timestamp
 */
void add_entry() {
    journal_entry new_entry;

    // Collect user input
    printf("\nEnter journal title: ");
    fgets(new_entry.title, MAX_TITLE, stdin);
    new_entry.title[strcspn(new_entry.title, "\n")] = 0; // Remove newline

    printf("Enter journal content: ");
    fgets(new_entry.content, MAX_CONTENT, stdin);
    new_entry.content[strcspn(new_entry.content, "\n")] = 0; // Remove newline

    // Generate ID and timestamp
    new_entry.id = make_id();
    get_time(new_entry.time);

    // Open file in append mode to add the new entry
    FILE *file = fopen(FILE_NAME, "a");

    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    // Write entry to file and close
    fprintf(file, "%d,%s,%s,%s\n", 
            new_entry.id, 
            new_entry.title, 
            new_entry.content, 
            new_entry.time);
    fclose(file);

    // Confirm success to user
    printf("\nJournal entry created successfully with ID: %d\n", new_entry.id);
    printf("Timestamp: %s\n", new_entry.time);
}

/**
 * Deletes a single journal entry based on its ID
 * First displays all entries so user can select one to delete
 */
void remove_entry() {
    int id_to_delete;
    FILE *file = fopen(FILE_NAME, "r");

    // Check if file exists
    if (file == NULL) {
        printf("No journal entries found.\n");
        return;
    }

    // Show all entries to help user choose which to delete
    show_entries();
    printf("\nEnter the ID of the entry you want to delete: ");
    scanf("%d", &id_to_delete);
    getchar(); // Consume newline

    // Create temporary file for entries we want to keep
    FILE *temp = fopen("temp.csv", "w");

    if (temp == NULL) {
        printf("Error creating temporary file!\n");
        fclose(file);
        return;
    }

    journal_entry current;
    char line[MAX_TITLE + MAX_CONTENT + MAX_TIME + 20];
    int found = 0;

    // Copy all entries except the one to be deleted
    while (fgets(line, sizeof(line), file)) {
        sscanf(line, "%d,%[^,],%[^,],%[^\n]", 
               &current.id, 
               current.title, 
               current.content, 
               current.time);

        if (current.id != id_to_delete) {
            fprintf(temp, "%d,%s,%s,%s\n", 
                    current.id, 
                    current.title, 
                    current.content, 
                    current.time);
        } else {
            found = 1;
        }
    }

    fclose(file);
    fclose(temp);

    // Replace original file with our filtered version
    if (found) {
        remove(FILE_NAME);
        rename("temp.csv", FILE_NAME);
        printf("Journal entry with ID %d deleted successfully.\n", id_to_delete);
    } else {
        remove("temp.csv");
        printf("Journal entry with ID %d not found.\n", id_to_delete);
    }
}

/**
 * Deletes all journal entries after confirmation from user
 * Creates a new empty file to replace the existing one
 */
void remove_all() {
    char answer;

    // Ask for confirmation before proceeding
    printf("Are you sure you want to delete all journal entries? (y/n): ");
    scanf("%c", &answer);
    getchar(); // Consume newline

    if (answer == 'y' || answer == 'Y') {
        // Open and immediately close file in write mode to clear it
        FILE *file = fopen(FILE_NAME, "w");
        fclose(file);
        printf("All journal entries deleted successfully.\n");
    } else {
        printf("Operation cancelled.\n");
    }
}
